/**
 * First-time setup: creates a brand-new Home for the signed-in user in ONE atomic batch.
 *
 *   homes/{homeId}                      home identity + core locale settings
 *   homes/{homeId}/members/{uid}        owner membership (authorization source)
 *   homes/{homeId}/roles/{roleId} x5    seeded system roles
 *   homes/{homeId}/settings/general     initial Home settings
 *   users/{uid}                         created, or updated with the new defaultHomeId
 *
 * The homeId is generated by Firestore. Firestore rules accept this batch only when the
 * creator is request.auth.uid and the owner membership belongs to that same user
 * (see "bootstrap" in firestore.rules / SECURITY.md).
 */
import { paths } from '../firebase/paths.js';
import { atomicWrite, newDocId, serverTime } from '../data/firestore.js';
import { AppError, ErrorCode, toAppError } from '../errors/app-error.js';
import { buildSetupWrites } from './setup-plan.js';
import { defaultRoles } from '../../modules/index.js';
import { log } from '../utils/logger.js';

export async function createHome(input) {
  const homeId = newDocId(paths.homes());
  const writes = buildSetupWrites({ ...input, homeId, roles: defaultRoles(), now: serverTime() });
  try {
    await atomicWrite((w) => { for (const { mode, path, data } of writes) w[mode](path, data); });
  } catch (err) {
    const e = toAppError(err, ErrorCode.SETUP_FAILED);
    throw e.code === ErrorCode.NETWORK ? e : new AppError(ErrorCode.SETUP_FAILED, { cause: err, detail: e.code });
  }
  log.info('Home created', `(${writes.length} documents in one batch)`);
  return homeId;
}
